import {NavDrawerElement} from './nav-drawer-element.js';

declare global {
  interface HTMLElementTagNameMap {
    /** A Material Design navigation drawer custom element. */
    'md-gb-nav-drawer': NavDrawerElement;
  }
}

if (!customElements.get('md-gb-nav-drawer')) {
  customElements.define('md-gb-nav-drawer', NavDrawerElement);
}
